import * as THREE from 'three';

export type SpringSlot = 1 | 2 | 3 | 4 | 5;

export interface CPOLauncherOptions {
  initialAngleDeg?: number;       // 0° to 90°
  springSlot?: SpringSlot;        // 1 to 5
  gravity?: number;               // m/s^2 (default 9.81)
  showProjectile?: boolean;
  barrelColor?: string;
  showPhotogates?: boolean;
  textureUrl?: string;            // custom front wood + markings texture URL
}

export interface CPOKinematics {
  launchVelocity: number;         // m/s
  elevationAngleDeg: number;      // degrees
  elevationAngleRad: number;      // radians
  rangeMeters: number;            // horizontal range
  maxHeightMeters: number;        // apex height
  flightTimeSeconds: number;      // time of flight
}

export interface CPOLauncherRig {
  group: THREE.Group;
  root: THREE.Group;
  setAngle: (deg: number) => void;
  setAngleDeg: (deg: number) => void;
  setSpringSlot: (slot: SpringSlot) => void;
  getKinematics: () => CPOKinematics;
  getMuzzleWorldPos: () => THREE.Vector3;
  launchMarble: (onComplete?: () => void) => void;
  dispose: () => void;
}

export const CPO_SLOT_VELOCITIES: Record<SpringSlot, number> = {
  1: 3.2,
  2: 4.0,
  3: 4.8,
  4: 5.5,
  5: 6.2,
};

export function createCPOMarbleLauncher(
  options: CPOLauncherOptions = {}
): CPOLauncherRig {
  let angleDeg = options.initialAngleDeg ?? 55;
  let springSlot: SpringSlot = options.springSlot ?? 3;
  let gravity = options.gravity ?? 9.81;

  const root = new THREE.Group();
  root.name = 'CPOMarbleLauncherRoot';

  // 1. Procedural 3D Extruded Wooden Frame (Warm natural honey-birch tone)
  const boardPoints = [
    [-0.5916, 0.816],
        [-0.0408, 0.8262],
        [0.0714, 0.765],
        [0.561, 0.765],
        [0.6936, 0.8874],
        [0.7446, 0.714],
        [0.7956, 0.714],
        [0.8568, 0.7548],
        [1.0404, 0.7956],
        [1.1118, 0.7446],
        [0.9282, 0.4386],
        [0.8364, 0.4182],
        [0.8466, -0.0408],
        [0.8976, -0.1836],
        [0.8874, -0.6324],
        [0.6324, -0.6426],
        [0.357, -0.5916],
        [0.1224, -0.4896],
        [-0.0816, -0.3468],
        [-0.255, -0.204],
        [-0.3264, -0.1428],
        [-0.408, -0.153],
        [-0.51, -0.2244],
        [-0.6528, -0.3774],
        [-0.816, -0.51],
        [-0.9792, -0.6222],
        [-1.0608, -0.7344],
        [-1.1832, -0.7956],
        [-1.1934, -0.7242],
        [-1.1424, -0.5304],
        [-1.071, -0.4488],
        [-0.9792, -0.3366],
        [-0.8874, -0.2142],
        [-0.7956, -0.0714],
        [-0.714, 0.0918],
        [-0.6426, 0.2958],
        [-0.6018, 0.5406]
  ];

  const frameShape = new THREE.Shape();
  frameShape.moveTo(boardPoints[0][0], boardPoints[0][1]);
  for (let i = 1; i < boardPoints.length; i++) {
    frameShape.lineTo(boardPoints[i][0], boardPoints[i][1]);
  }
  frameShape.closePath();

  // Concentric curved through-slot hole
  const pivotX = 0.7585;
  const pivotY = 0.687;
  const rSlot = 1.1029;
  const r1 = rSlot - 0.036;
  const r2 = rSlot + 0.036;

  const slotHole = new THREE.Path();
  const segs = 36;
  for (let i = 0; i <= segs; i++) {
    const a = Math.PI + (i / segs) * (Math.PI * 0.5);
    const x = pivotX + r2 * Math.cos(a);
    const y = pivotY + r2 * Math.sin(a);
    if (i === 0) slotHole.moveTo(x, y);
    else slotHole.lineTo(x, y);
  }
  for (let i = 0; i <= 8; i++) {
    const a = -Math.PI * 0.5 - (i / 8) * Math.PI;
    const x = pivotX + (r1 + r2) * 0.5 * Math.cos(Math.PI * 1.5) + (r2 - r1) * 0.5 * Math.cos(a);
    const y = pivotY + (r1 + r2) * 0.5 * Math.sin(Math.PI * 1.5) + (r2 - r1) * 0.5 * Math.sin(a);
    slotHole.lineTo(x, y);
  }
  for (let i = segs; i >= 0; i--) {
    const a = Math.PI + (i / segs) * (Math.PI * 0.5);
    const x = pivotX + r1 * Math.cos(a);
    const y = pivotY + r1 * Math.sin(a);
    slotHole.lineTo(x, y);
  }
  for (let i = 0; i <= 8; i++) {
    const a = Math.PI - (i / 8) * Math.PI;
    const x = pivotX + (r1 + r2) * 0.5 * Math.cos(Math.PI) + (r2 - r1) * 0.5 * Math.cos(a);
    const y = pivotY + (r1 + r2) * 0.5 * Math.sin(Math.PI) + (r2 - r1) * 0.5 * Math.sin(a);
    slotHole.lineTo(x, y);
  }
  frameShape.holes.push(slotHole);

  const woodDepth = 0.075;
  const extrudeSettings: THREE.ExtrudeGeometryOptions = {
    depth: woodDepth,
    bevelEnabled: false
  };

  const woodMat = new THREE.MeshStandardMaterial({
    color: 0xc89058,
    roughness: 0.72,
    metalness: 0.02
  });

  const frameMesh = new THREE.Mesh(new THREE.ExtrudeGeometry(frameShape, extrudeSettings), woodMat);
  frameMesh.position.set(0, 0, 0);
  frameMesh.castShadow = true;
  frameMesh.receiveShadow = true;
  root.add(frameMesh);

  // 2. Opaque Front Wooden Surface with Clean Vector Markings (Zero Z-fighting or transparency sorting issues)
  const frontGeo = new THREE.ShapeGeometry(frameShape);
  const posAttr = frontGeo.attributes.position;
  const uvArray = new Float32Array(posAttr.count * 2);
  for (let i = 0; i < posAttr.count; i++) {
    const x = posAttr.getX(i);
    const y = posAttr.getY(i);
    uvArray[i * 2] = (x + 1.224) / 2.55;
    uvArray[i * 2 + 1] = (y + 1.275) / 2.55;
  }
  frontGeo.setAttribute('uv', new THREE.BufferAttribute(uvArray, 2));

  const frontMat = new THREE.MeshStandardMaterial({
    color: woodMat.color,
    roughness: 0.70,
    metalness: 0.02,
    polygonOffset: true,
    polygonOffsetFactor: -2,
    polygonOffsetUnits: -2
  });
  // The picker renders immediately, so use wood color until the image has decoded.
  new THREE.TextureLoader().load(options.textureUrl || 'data:image/jpeg;base64,', (texture) => {
    texture.colorSpace = THREE.SRGBColorSpace;
    texture.anisotropy = 8;
    frontMat.map = texture;
    frontMat.color.set(0xffffff);
    frontMat.needsUpdate = true;
  });
  const frontMesh = new THREE.Mesh(frontGeo, frontMat);
  frontMesh.position.set(0, 0, woodDepth + 0.0008);
  root.add(frontMesh);

  // 3. Right Support Foot (Standalone wooden piece bolted flush to right rear)
  const footShape = new THREE.Shape();
  footShape.moveTo(0.88, -0.17);
  footShape.lineTo(1.02, -0.17);
  footShape.lineTo(1.25, -0.82);
  footShape.lineTo(1.11, -0.82);
  footShape.closePath();

  const footMesh = new THREE.Mesh(new THREE.ExtrudeGeometry(footShape, { depth: 0.07, bevelEnabled: false }), woodMat);
  // Mounted flush against the rear face of the frame (z = -0.07 to z = 0) with zero disconnect
  footMesh.position.set(0, 0, -0.07);
  footMesh.castShadow = true;
  footMesh.receiveShadow = true;
  root.add(footMesh);

  const silverMat = new THREE.MeshStandardMaterial({ color: 0xe2e8f0, roughness: 0.32, metalness: 0.22 });

  // Carriage bolt fastening rear foot to frame (passing through frame z in [0, 0.075] and foot z in [-0.07, 0])
  const pivotBolt = new THREE.Mesh(new THREE.CylinderGeometry(0.018, 0.018, 0.22, 16), silverMat);
  pivotBolt.geometry.rotateX(Math.PI * 0.5);
  pivotBolt.position.set(0.96, -0.32, 0);
  pivotBolt.castShadow = true;
  root.add(pivotBolt);

  // Front carriage bolt head
  const boltHead = new THREE.Mesh(new THREE.CylinderGeometry(0.032, 0.032, 0.012, 20), silverMat);
  boltHead.geometry.rotateX(Math.PI * 0.5);
  boltHead.position.set(0.96, -0.32, woodDepth + 0.006);
  root.add(boltHead);

  // Rear clamping wingnut & washer
  const rearWingnut = new THREE.Mesh(new THREE.BoxGeometry(0.055, 0.018, 0.014), silverMat);
  rearWingnut.position.set(0.96, -0.32, -0.07 - 0.012);
  root.add(rearWingnut);

  // 4. Slotted Satin-Silver Barrel Assembly with Visible Internal Spring & Phillips Breech Block
  const pivotPos = new THREE.Vector3(pivotX, pivotY, woodDepth + 0.055);
  const barrelAssembly = new THREE.Group();
  barrelAssembly.position.copy(pivotPos);
  root.add(barrelAssembly);

  const blackMat = new THREE.MeshStandardMaterial({ color: 0x18181b, roughness: 0.50 });
  const barrelMat = options.barrelColor ? new THREE.MeshStandardMaterial({
    color: options.barrelColor, roughness: .32, metalness: .38,
  }) : silverMat;
  const boreMat = new THREE.MeshStandardMaterial({ color: 0x09090b, roughness: 0.85 });
  const springSteelMat = new THREE.MeshStandardMaterial({ color: 0xf8fafc, roughness: 0.22, metalness: 0.25 });

  // 4a. Lower solid satin-silver barrel section (x = -1.04 to -0.82)
  const lowerBarrelGeo = new THREE.CylinderGeometry(0.066, 0.066, 0.22, 24);
  lowerBarrelGeo.rotateZ(Math.PI * 0.5);
  const lowerBarrelMesh = new THREE.Mesh(lowerBarrelGeo, barrelMat);
  lowerBarrelMesh.position.set(-0.93, 0, 0);
  lowerBarrelMesh.castShadow = true;
  barrelAssembly.add(lowerBarrelMesh);

  // 4b. Middle open-slotted window section (x = -0.82 to -0.14, length = 0.68)
  const midBackGeo = new THREE.CylinderGeometry(0.066, 0.066, 0.68, 24, 1, false, Math.PI * 0.55, Math.PI * 1.15);
  midBackGeo.rotateZ(Math.PI * 0.5);
  const midBackMesh = new THREE.Mesh(midBackGeo, barrelMat);
  midBackMesh.position.set(-0.48, 0, 0);
  barrelAssembly.add(midBackMesh);

  // Dark recessed interior bore behind spring so spring coils pop clearly
  const boreBackMesh = new THREE.Mesh(new THREE.BoxGeometry(0.68, 0.082, 0.02), boreMat);
  boreBackMesh.position.set(-0.48, 0, -0.022);
  barrelAssembly.add(boreBackMesh);

  // Top & bottom satin-silver longitudinal rails framing the open spring window
  const topRail = new THREE.Mesh(new THREE.BoxGeometry(0.68, 0.022, 0.048), barrelMat);
  topRail.position.set(-0.48, 0.054, 0.022);
  barrelAssembly.add(topRail);

  const botRail = new THREE.Mesh(new THREE.BoxGeometry(0.68, 0.022, 0.048), barrelMat);
  botRail.position.set(-0.48, -0.054, 0.022);
  barrelAssembly.add(botRail);

  // 5 Speed Notches (L-slots 1 to 5) cut along the upper rail
  for (let s = 1; s <= 5; s++) {
    const nx = -0.70 + (s - 1) * 0.11;
    const notch = new THREE.Mesh(new THREE.BoxGeometry(0.026, 0.032, 0.054), boreMat);
    notch.position.set(nx, 0.042, 0.025);
    barrelAssembly.add(notch);
  }

  // 4c. Upper solid satin-silver barrel & muzzle section (x = -0.14 to +0.24, length = 0.38)
  const upperBarrelGeo = new THREE.CylinderGeometry(0.066, 0.066, 0.38, 24);
  upperBarrelGeo.rotateZ(Math.PI * 0.5);
  const upperBarrelMesh = new THREE.Mesh(upperBarrelGeo, barrelMat);
  upperBarrelMesh.position.set(0.05, 0, 0);
  upperBarrelMesh.castShadow = true;
  barrelAssembly.add(upperBarrelMesh);

  // Dark muzzle bore opening at x = +0.24
  const muzzleBoreGeo = new THREE.CylinderGeometry(0.052, 0.052, 0.02, 24);
  muzzleBoreGeo.rotateZ(Math.PI * 0.5);
  const muzzleBore = new THREE.Mesh(muzzleBoreGeo, boreMat);
  muzzleBore.position.set(0.235, 0, 0);
  barrelAssembly.add(muzzleBore);

  // CPO Science Dual Photogate Timer Bracket (#263-2310) at Muzzle Exit
  if (options.showPhotogates !== false) {
    const cpoGates = new THREE.Group();
    cpoGates.position.set(0.24, 0, 0);

    const cpoPgMat = new THREE.MeshStandardMaterial({ color: 0x1e293b, roughness: 0.45, metalness: 0.55 });
    const cpoClamp = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.02, 0.16), cpoPgMat);
    cpoClamp.position.set(-0.02, -0.076, 0);
    cpoGates.add(cpoClamp);

    const cpoRail = new THREE.Mesh(new THREE.BoxGeometry(0.16, 0.016, 0.022), cpoPgMat);
    cpoRail.position.set(0.05, -0.082, 0);
    cpoGates.add(cpoRail);

    for (const gx of [0.025, 0.115]) {
      const uBeam = new THREE.Mesh(new THREE.BoxGeometry(0.018, 0.014, 0.18), cpoPgMat);
      uBeam.position.set(gx, -0.082, 0);
      cpoGates.add(uBeam);

      for (const zSide of [-0.09, 0.09]) {
        const arm = new THREE.Mesh(new THREE.BoxGeometry(0.015, 0.16, 0.016), cpoPgMat);
        arm.position.set(gx, 0, zSide);
        cpoGates.add(arm);

        const eyeMat = zSide < 0
          ? new THREE.MeshBasicMaterial({ color: 0xef4444 })
          : new THREE.MeshBasicMaterial({ color: 0x090d16 });
        const eye = new THREE.Mesh(new THREE.CylinderGeometry(0.005, 0.005, 0.006, 12), eyeMat);
        eye.rotation.x = Math.PI * 0.5;
        eye.position.set(gx, 0, zSide - (zSide < 0 ? -0.006 : 0.006));
        cpoGates.add(eye);
      }

      const led = new THREE.Mesh(
        new THREE.SphereGeometry(0.004, 10, 10),
        new THREE.MeshBasicMaterial({ color: 0x22c55e })
      );
      led.position.set(gx, 0.082, -0.09);
      cpoGates.add(led);
    }
    barrelAssembly.add(cpoGates);
  }

  // 4d. Double Black O-Ring Collar at Upper Pivot Saddle (x = -0.015 and +0.025)
  for (const cxOff of [-0.015, 0.025]) {
    const oRing = new THREE.Mesh(new THREE.TorusGeometry(0.068, 0.016, 16, 32), blackMat);
    oRing.rotation.y = Math.PI * 0.5;
    oRing.position.set(cxOff, 0, 0);
    barrelAssembly.add(oRing);
  }

  // Pivot Trunnion Shaft passing from barrel saddle through wooden frame
  const trunnionShaft = new THREE.Mesh(
    new THREE.CylinderGeometry(0.032, 0.032, 0.16, 20),
    silverMat
  );
  trunnionShaft.geometry.rotateX(Math.PI * 0.5);
  trunnionShaft.position.set(0.005, 0, -0.055);
  trunnionShaft.castShadow = true;
  barrelAssembly.add(trunnionShaft);

  // 4e. Lower Rectangular Black Breech Block & Silver Phillips Screw at x = -rSlot (-1.1029)
  const breechBlock = new THREE.Mesh(new THREE.BoxGeometry(0.125, 0.128, 0.115), blackMat);
  breechBlock.position.set(-rSlot, 0, 0);
  barrelAssembly.add(breechBlock);

  const screwHead = new THREE.Mesh(new THREE.CylinderGeometry(0.042, 0.042, 0.02, 20), silverMat);
  screwHead.geometry.rotateX(Math.PI * 0.5);
  screwHead.position.set(-rSlot, 0, 0.055);
  barrelAssembly.add(screwHead);

  // Phillips cross (+) on screw head
  const crossH = new THREE.Mesh(new THREE.BoxGeometry(0.052, 0.012, 0.008), blackMat);
  crossH.position.set(-rSlot, 0, 0.064);
  barrelAssembly.add(crossH);
  const crossV = new THREE.Mesh(new THREE.BoxGeometry(0.012, 0.052, 0.008), blackMat);
  crossV.position.set(-rSlot, 0, 0.064);
  barrelAssembly.add(crossV);

  // Guide shaft passing straight through the curved wooden slot
  const guideScrew = new THREE.Mesh(new THREE.CylinderGeometry(0.028, 0.028, 0.24, 16), silverMat);
  guideScrew.geometry.rotateX(Math.PI * 0.5);
  guideScrew.position.set(-rSlot, 0, -0.06);
  barrelAssembly.add(guideScrew);

  // 4f. Docked Glass Marble at Muzzle Tip (rotates synchronously with barrelAssembly)
  const darkGreenMat = new THREE.MeshStandardMaterial({ color: 0x065f46, roughness: 0.15, metalness: 0.15 });
  const marbleMesh = new THREE.Mesh(new THREE.SphereGeometry(0.046, 24, 24), darkGreenMat);
  marbleMesh.position.set(0.25, 0, 0);
  marbleMesh.visible = options.showProjectile ?? true;
  marbleMesh.castShadow = true;
  barrelAssembly.add(marbleMesh);

  // 4g. Exposed Internal Helical Spring, Plunger & Trigger Handle Pin
  const plungerHead = new THREE.Mesh(new THREE.CylinderGeometry(0.044, 0.044, 0.055, 20), blackMat);
  plungerHead.geometry.rotateZ(Math.PI * 0.5);
  barrelAssembly.add(plungerHead);

  const leverPin = new THREE.Mesh(new THREE.CylinderGeometry(0.014, 0.014, 0.14, 12), silverMat);
  leverPin.geometry.rotateX(Math.PI * 0.5);
  barrelAssembly.add(leverPin);

  let springMesh: THREE.Mesh | null = null;
  function updateSpringGeometry(slot: SpringSlot) {
    if (springMesh) {
      barrelAssembly.remove(springMesh);
      springMesh.geometry.dispose();
    }
    const startX = -0.82;
    const endX = -0.70 + (slot - 1) * 0.11;
    const pts: THREE.Vector3[] = [];
    const coils = 13;
    for (let i = 0; i <= 90; i++) {
      const t = i / 90;
      const x = startX + (endX - startX) * t;
      const theta = t * coils * Math.PI * 2;
      pts.push(new THREE.Vector3(x, Math.sin(theta) * 0.036, 0.01 + Math.cos(theta) * 0.036));
    }
    springMesh = new THREE.Mesh(
      new THREE.TubeGeometry(new THREE.CatmullRomCurve3(pts), 80, 0.0085, 8, false),
      springSteelMat
    );
    barrelAssembly.add(springMesh);

    plungerHead.position.set(endX + 0.028, 0, 0.01);
    leverPin.position.set(endX + 0.028, 0.042, 0.05);
  }

  function applyRigState() {
    barrelAssembly.rotation.z = (angleDeg * Math.PI) / 180;
    updateSpringGeometry(springSlot);
  }
  applyRigState();

  const setAngleFn = (deg: number) => {
    angleDeg = Math.max(0, Math.min(90, deg));
    applyRigState();
  };

  return {
    group: root,
    root,
    setAngle: setAngleFn,
    setAngleDeg: setAngleFn,
    setSpringSlot(slot: SpringSlot) {
      springSlot = slot;
      applyRigState();
    },
    getMuzzleWorldPos(): THREE.Vector3 {
      const rad = (angleDeg * Math.PI) / 180;
      // Analytical muzzle position in cpoRig local coordinates:
      // pivotPos is at (0.24, 0.44, woodDepth + 0.055) and marble sits at x = +0.25 in barrelAssembly
      return new THREE.Vector3(
        pivotX + 0.25 * Math.cos(rad),
        pivotY + 0.25 * Math.sin(rad),
        woodDepth + 0.055
      );
    },
    getKinematics(): CPOKinematics {
      const v0 = CPO_SLOT_VELOCITIES[springSlot];
      const rad = (angleDeg * Math.PI) / 180;
      const vx = v0 * Math.cos(rad);
      const vy = v0 * Math.sin(rad);
      const t = (2 * vy) / gravity;
      const range = (v0 * v0 * Math.sin(2 * rad)) / gravity;
      const hMax = (vy * vy) / (2 * gravity);
      return {
        launchVelocity: v0,
        elevationAngleDeg: angleDeg,
        elevationAngleRad: rad,
        rangeMeters: Math.max(0, range),
        maxHeightMeters: Math.max(0, hMax),
        flightTimeSeconds: Math.max(0, t),
      };
    },
    launchMarble(onComplete?: () => void) {
      if (onComplete) onComplete();
    },
    dispose() {
      root.traverse((child) => {
        if (child instanceof THREE.Mesh) {
          child.geometry.dispose();
          if (Array.isArray(child.material)) child.material.forEach(m => m.dispose());
          else child.material.dispose();
        }
      });
    }
  };
}
